import{_ as e,a,o,ai as n}from"./chunks/framework.BbOtTPsL.js";const h=JSON.parse('{"title":"Attribute Translations","description":"","frontmatter":{"outline":false,"examples":[{"id":"list-attribute-translations","title":"List Attribute Translations","description":"Retrieve a paginated, flat list of attribute translations across all locales.","request":"curl -X GET \\"http://localhost/api/shop/attribute_translations?per_page=2\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"X-STOREFRONT-KEY: pk_storefront_xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx\\"\\n","response":"HTTP/1.1 200 OK\\nX-Total-Count: 47\\nX-Page: 1\\nX-Per-Page: 2\\nX-Total-Pages: 24\\n\\n[\\n  { \\"id\\": 1, \\"attributeId\\": 1, \\"locale\\": \\"en\\", \\"name\\": \\"SKU\\" },\\n  { \\"id\\": 2, \\"attributeId\\": 2, \\"locale\\": \\"en\\", \\"name\\": \\"Name\\" }\\n]\\n","commonErrors":[{"error":"401 Unauthorized","cause":"Missing or invalid `X-STOREFRONT-KEY`","solution":"Send a valid storefront API key."}]},{"id":"get-attribute-translation","title":"Get Single Attribute Translation","description":"Retrieve a single attribute translation by ID. Typically reached by following an entry from the `translations[]` array of an Attribute response.","request":"curl -X GET \\"http://localhost/api/shop/attribute_translations/1\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"X-STOREFRONT-KEY: pk_storefront_xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx\\"\\n","response":"HTTP/1.1 200 OK\\n\\n{ \\"id\\": 1, \\"attributeId\\": 1, \\"locale\\": \\"en\\", \\"name\\": \\"SKU\\" }\\n","commonErrors":[{"error":"404 Not Found","cause":"No translation with the given `{id}` exists","solution":"List translations via `GET /api/shop/attribute_translations` or read the parent attribute\'s `translations[]` array."},{"error":"401 Unauthorized","cause":"Missing or invalid `X-STOREFRONT-KEY`","solution":"Send a valid storefront API key."}]}]},"headers":[],"relativePath":"api/rest-api/shop/attributes/get-attribute-translations.md","filePath":"api/rest-api/shop/attributes/get-attribute-translations.md","lastUpdated":1781099665000}'),r={name:"api/rest-api/shop/attributes/get-attribute-translations.md"};function s(i,t,l,d,c,p){return o(),a("div",null,t[0]||(t[0]=[n(`<h1 id="attribute-translations" tabindex="-1">Attribute Translations <a class="header-anchor" href="#attribute-translations" aria-label="Permalink to &quot;Attribute Translations&quot;">​</a></h1><p>Locale-specific names for attributes. The single endpoint is the destination of the IRI strings emitted in the <code>translations[]</code> array of <a href="/api/rest-api/shop/attributes/get-attributes.html"><code>GET /api/shop/attributes/{id}</code></a> — for example <code>/api/shop/attribute_translations/23</code>.</p><blockquote><p>⚠️ The URL uses an <strong>underscore</strong>: <code>attribute_translations</code>, not <code>attribute-translations</code>.</p></blockquote><p>Most clients won&#39;t call this collection directly — they&#39;ll either:</p><ul><li>read the inline <code>translation</code> object on the parent attribute (current locale only), or</li><li>follow a <code>translations[]</code> IRI for a single non-default locale.</li></ul><p>Use these endpoints when you need to bulk-load every translation (e.g. for offline caching) or audit translation completeness.</p><h2 id="endpoints" tabindex="-1">Endpoints <a class="header-anchor" href="#endpoints" aria-label="Permalink to &quot;Endpoints&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Purpose</th></tr></thead><tbody><tr><td>GET</td><td><code>/api/shop/attribute_translations</code></td><td>Paginated flat list of every translation</td></tr><tr><td>GET</td><td><code>/api/shop/attribute_translations/{id}</code></td><td>Single translation by ID</td></tr></tbody></table><h2 id="request-headers" tabindex="-1">Request Headers <a class="header-anchor" href="#request-headers" aria-label="Permalink to &quot;Request Headers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Header</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>Accept</code></td><td>Yes</td><td><code>application/json</code></td></tr><tr><td><code>X-STOREFRONT-KEY</code></td><td>Yes</td><td>Storefront API key (<code>pk_storefront_…</code>)</td></tr></tbody></table><h2 id="query-parameters-collection-only" tabindex="-1">Query Parameters (collection only) <a class="header-anchor" href="#query-parameters-collection-only" aria-label="Permalink to &quot;Query Parameters (collection only)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>page</code></td><td>integer</td><td>1</td><td>Page number (1-based)</td></tr><tr><td><code>per_page</code></td><td>integer</td><td>10</td><td>Items per page. Max <strong>50</strong>.</td></tr></tbody></table><p>Pagination headers are emitted on the collection. See <a href="/api/rest-api/introduction.html#pagination">Pagination</a>.</p><h2 id="translation-object-fields" tabindex="-1">Translation Object Fields <a class="header-anchor" href="#translation-object-fields" aria-label="Permalink to &quot;Translation Object Fields&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>integer</td><td>Translation primary key</td></tr><tr><td><code>attributeId</code></td><td>integer</td><td>Owning attribute&#39;s ID — fetch via <code>GET /api/shop/attributes/{attributeId}</code></td></tr><tr><td><code>locale</code></td><td>string</td><td>Locale code (e.g. <code>en</code>, <code>fr</code>, <code>de</code>, <code>ar</code>)</td></tr><tr><td><code>name</code></td><td>string</td><td>Localized attribute name shown to customers in that locale</td></tr></tbody></table><h2 id="typical-flow" tabindex="-1">Typical Flow <a class="header-anchor" href="#typical-flow" aria-label="Permalink to &quot;Typical Flow&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /api/shop/attributes/23</span></span>
<span class="line"><span>   └─ response.translations = [</span></span>
<span class="line"><span>        &quot;/api/shop/attribute_translations/23&quot;,</span></span>
<span class="line"><span>        &quot;/api/shop/attribute_translations/156&quot;,</span></span>
<span class="line"><span>        ...</span></span>
<span class="line"><span>      ]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>GET /api/shop/attribute_translations/156</span></span>
<span class="line"><span>   └─ { &quot;id&quot;: 156, &quot;attributeId&quot;: 23, &quot;locale&quot;: &quot;fr&quot;, &quot;name&quot;: &quot;Couleur&quot; }</span></span></code></pre></div><p>You don&#39;t need to know the translation ID up front — read the <code>translations[]</code> array on the attribute and dereference any entry you need.</p><h2 id="use-cases" tabindex="-1">Use Cases <a class="header-anchor" href="#use-cases" aria-label="Permalink to &quot;Use Cases&quot;">​</a></h2><ul><li>Pre-populate a localized admin tool that lets store managers review every attribute translation in one view.</li><li>Build an offline cache of all attribute names per locale for an SPA.</li><li>Validate translation completeness — sort/filter by locale and check for empty <code>name</code> values.</li></ul><h2 id="related-resources" tabindex="-1">Related Resources <a class="header-anchor" href="#related-resources" aria-label="Permalink to &quot;Related Resources&quot;">​</a></h2><ul><li><a href="/api/rest-api/shop/attributes/get-attributes.html">Attributes</a> — returns inline <code>translation</code> for the request locale and <code>translations[]</code> IRIs for the rest</li><li><a href="/api/rest-api/shop/attributes/get-attribute-options.html">Attribute Options</a></li><li><a href="/api/rest-api/introduction.html#iris-hateoas">Introduction → IRIs &amp; HATEOAS</a></li></ul>`,22)]))}const b=e(r,[["render",s]]);export{h as __pageData,b as default};
